const { createRequire } = require('node:module');
const { join } = require('node:path');
const { mkdirSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');

const URL = 'http://127.0.0.1:3002/';
const OUT = '/tmp/opencode/shots';
mkdirSync(OUT, { recursive: true });

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  await context.grantPermissions(['clipboard-read', 'clipboard-write']);
  const page = await context.newPage();
  const problems = [];
  page.on('pageerror', (e) => problems.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') problems.push('console: ' + m.text()); });
  page.on('requestfailed', (r) => problems.push('requestfailed: ' + r.url() + ' ' + (r.failure()?.errorText || '')));

  const res = await page.goto(URL, { waitUntil: 'networkidle' });
  console.log('status', res.status());
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(900);

  console.log('title', await page.title());
  console.log('cards', await page.locator('.req-card').count());
  console.log('qr loaded', await page.locator('.qr-img').evaluateAll((imgs) => imgs.map((i) => ({ w: i.naturalWidth, h: i.naturalHeight, src: i.src.slice(0, 30) }))));
  console.log('stats', await page.locator('.hero-stats dd').allTextContents());
  console.log('overflow-x', await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));

  await page.screenshot({ path: join(OUT, 'desktop-full.png'), fullPage: true });
  await page.screenshot({ path: join(OUT, 'desktop-hero.png') });

  // sheet fit and overflow
  const sheetInfo = await page.evaluate(() => {
    const out = {};
    for (const kind of ['poster', 'flyer']) {
      const sheet = document.querySelector('.sheet-' + kind);
      const frame = sheet.closest('.sheet-frame');
      const inner = sheet.querySelector('.sheet-inner');
      const tabs = sheet.querySelector('.sheet-tabs');
      const r = sheet.getBoundingClientRect();
      const ir = inner.getBoundingClientRect();
      out[kind] = {
        frameW: frame.clientWidth, frameH: frame.clientHeight,
        sheetW: sheet.offsetWidth, sheetH: sheet.offsetHeight,
        scaleW: +(r.width / sheet.offsetWidth).toFixed(3),
        innerBottom: +(ir.bottom - r.top).toFixed(1),
        tabsBottom: +(tabs.getBoundingClientRect().bottom - r.top).toFixed(1),
        overflow: inner.scrollHeight - inner.clientHeight
      };
    }
    return out;
  });
  console.log('sheets', JSON.stringify(sheetInfo, null, 2));

  // switch to flyer
  await page.getByRole('tab', { name: 'Panfleto A5' }).click();
  await page.waitForTimeout(500);
  console.log('flyer visible', await page.locator('.sheet-flyer').isVisible(), 'poster hidden', !(await page.locator('.sheet-poster').isVisible()));
  await page.locator('#materiais').screenshot({ path: join(OUT, 'materials-flyer.png') });
  await page.getByRole('tab', { name: 'Cartaz A4' }).click();
  await page.waitForTimeout(400);
  await page.locator('#materiais').screenshot({ path: join(OUT, 'materials-poster.png') });

  // form flow
  await page.locator('#preciso-de-ajuda').scrollIntoViewIfNeeded();
  await page.fill('#f-name', 'Teste da Silva');
  await page.fill('#f-phone', '11987654321');
  await page.fill('#f-hood', 'Bairro Teste');
  await page.fill('#f-city', 'São Paulo');
  await page.selectOption('#f-people', '3');
  await page.fill('#f-reason', 'Preciso de ajuda para cozinhar para meus filhos esta semana.');
  await page.check('#f-consent');
  await page.locator('#request-form button[type=submit]').click();
  await page.waitForTimeout(500);
  console.log('dialog open', await page.locator('#success-dialog').evaluate((d) => d.open));
  const shareLink = await page.inputValue('#share-link');
  console.log('share link length', shareLink.length, shareLink.slice(0, 90));
  console.log('success wa', (await page.getAttribute('#success-wa', 'href')).slice(0, 90));
  await page.screenshot({ path: join(OUT, 'success-dialog.png') });
  await page.locator('#view-request').click();
  await page.waitForTimeout(700);
  console.log('cards after submit', await page.locator('.req-card').count());
  console.log('new card', await page.locator('.req-card', { hasText: 'Teste' }).count());
  await page.locator('#pedidos').screenshot({ path: join(OUT, 'board.png') });

  // WhatsApp popup from new card
  const [popup] = await Promise.all([
    context.waitForEvent('page', { timeout: 5000 }).catch(() => null),
    page.locator('.req-card', { hasText: 'Teste' }).locator('[data-action=help]').click()
  ]);
  if (popup) {
    await popup.waitForLoadState('domcontentloaded').catch(() => {});
    console.log('popup url', popup.url().slice(0, 140));
    await popup.close();
  } else {
    console.log('popup: none');
  }

  // settings
  await page.getByRole('button', { name: /Configurar campanha/ }).click();
  await page.waitForTimeout(300);
  await page.fill('#s-name', 'Gás do Bairro');
  await page.fill('#s-wa', '5511912345678');
  await page.fill('#s-pix', 'pix@example.org');
  await page.locator('#settings-form button[type=submit]').click();
  await page.waitForTimeout(500);
  console.log('brand after save', await page.locator('.brand-name').first().textContent());
  console.log('phone after save', await page.locator('.poster-phone strong').textContent());
  console.log('pix visible', await page.locator('#pix-card').isVisible());
  console.log('pix key', await page.locator('#pix-key').textContent());
  await page.screenshot({ path: join(OUT, 'desktop-after-settings.png'), fullPage: true });

  // shared link open in fresh context
  const sharePage = await context.newPage();
  await sharePage.goto(shareLink, { waitUntil: 'networkidle' });
  await sharePage.waitForTimeout(1200);
  console.log('shared cards', await sharePage.locator('.req-card').count());
  console.log('shared highlight', await sharePage.locator('.req-card.is-shared').count());
  console.log('shared name', await sharePage.locator('.req-card.is-shared .req-name').textContent().catch(() => 'none'));
  await sharePage.screenshot({ path: join(OUT, 'shared-link.png'), fullPage: true });
  await sharePage.close();

  // print pdf
  await page.evaluate(() => {
    const sheet = document.querySelector('.sheet-poster');
    const stage = document.getElementById('print-stage');
    stage.innerHTML = '';
    const clone = sheet.cloneNode(true);
    clone.style.transform = 'none';
    stage.appendChild(clone);
    document.body.dataset.print = 'poster';
  });
  await page.emulateMedia({ media: 'print' });
  await page.pdf({ path: join(OUT, 'poster.pdf'), printBackground: true, preferCSSPageSize: true });
  await page.emulateMedia({ media: 'screen' });

  // mobile
  const mobile = await context.newPage();
  await mobile.setViewportSize({ width: 390, height: 844 });
  await mobile.goto(URL, { waitUntil: 'networkidle' });
  await mobile.evaluate(() => document.fonts.ready);
  await mobile.waitForTimeout(900);
  console.log('mobile overflow-x', await mobile.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));
  await mobile.screenshot({ path: join(OUT, 'mobile-full.png'), fullPage: true });
  await mobile.locator('#preciso-de-ajuda').scrollIntoViewIfNeeded();
  await mobile.waitForTimeout(500);
  await mobile.screenshot({ path: join(OUT, 'mobile-form.png') });
  await mobile.locator('#materiais').scrollIntoViewIfNeeded();
  await mobile.waitForTimeout(600);
  await mobile.screenshot({ path: join(OUT, 'mobile-materials.png') });

  console.log('PROBLEMS', problems.length ? problems : 'none');
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

