const { createRequire } = require('node:module');
const { join } = require('node:path');
const { mkdirSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');

const URL = 'http://127.0.0.1:3002/';
const OUT = '/tmp/opencode/shots2';
mkdirSync(OUT, { recursive: true });

async function revealAll(page) {
  const h = await page.evaluate(() => document.body.scrollHeight);
  for (let y = 0; y < h; y += 600) {
    await page.evaluate((v) => window.scrollTo(0, v), y);
    await page.waitForTimeout(80);
  }
  await page.evaluate(() => window.scrollTo(0, 0));
  await page.waitForTimeout(500);
}

(async () => {
  const browser = await chromium.launch({ headless: true });
  const context = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await context.newPage();
  const problems = [];
  page.on('pageerror', (e) => problems.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') problems.push('console: ' + m.text()); });
  page.on('requestfailed', (r) => problems.push('requestfailed: ' + r.url()));

  await page.goto(URL, { waitUntil: 'networkidle' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'networkidle' });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForTimeout(700);

  await page.screenshot({ path: join(OUT, 'hero.png') });

  for (const [id, name] of [['como-funciona', 'how'], ['pedidos', 'board'], ['preciso-de-ajuda', 'ask'], ['materiais', 'materials'], ['outras-formas', 'help']]) {
    await page.locator('#' + id).scrollIntoViewIfNeeded();
    await page.waitForTimeout(700);
    await page.screenshot({ path: join(OUT, `section-${name}.png`) });
  }

  // flyer preview after layout
  await page.getByRole('tab', { name: 'Panfleto A5' }).click();
  await page.waitForTimeout(400);
  await page.locator('#materiais').screenshot({ path: join(OUT, 'materials-flyer.png') });
  await page.getByRole('tab', { name: 'Cartaz A4' }).click();
  await page.waitForTimeout(400);

  // settings + privacy dialogs
  await page.getByRole('button', { name: /Configurar campanha/ }).click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: join(OUT, 'settings.png') });
  await page.keyboard.press('Escape');
  await page.locator('footer').getByRole('button', { name: /Como tratamos/ }).click();
  await page.waitForTimeout(300);
  await page.screenshot({ path: join(OUT, 'privacy.png') });
  await page.keyboard.press('Escape');

  // full page after reveals
  await revealAll(page);
  await page.screenshot({ path: join(OUT, 'full-desktop.png'), fullPage: true });

  // form flow
  await page.fill('#f-name', 'Maria Aparecida');
  await page.fill('#f-phone', '11987654321');
  await page.fill('#f-hood', 'Jardim das Flores');
  await page.fill('#f-city', 'São Paulo');
  await page.selectOption('#f-people', '4');
  await page.fill('#f-reason', 'O gás acabou e estou sem trabalho esta semana. Tenho três crianças em casa.');
  await page.locator('input[name="urgency"][value="urgente"]').check();
  await page.check('#f-consent');
  await page.locator('#request-form button[type=submit]').click();
  await page.waitForTimeout(600);
  await page.screenshot({ path: join(OUT, 'success.png') });
  console.log('success open', await page.locator('#success-dialog').evaluate((d) => d.open));
  const shareLink = await page.inputValue('#share-link');
  await page.locator('#view-request').click();
  await page.waitForTimeout(900);
  await page.screenshot({ path: join(OUT, 'board-new.png') });

  // print poster PDF
  await page.evaluate(() => {
    const stage = document.getElementById('print-stage');
    stage.innerHTML = '';
    const clone = document.querySelector('.sheet-poster').cloneNode(true);
    clone.style.transform = 'none';
    stage.appendChild(clone);
    document.body.dataset.print = 'poster';
  });
  await page.emulateMedia({ media: 'print' });
  await page.pdf({ path: join(OUT, 'poster.pdf'), printBackground: true, preferCSSPageSize: true });
  await page.emulateMedia({ media: 'screen' });
  await page.evaluate(() => { document.body.dataset.print = ''; document.getElementById('print-stage').innerHTML = ''; });

  // flyer print PDF
  await page.evaluate(() => {
    const stage = document.getElementById('print-stage');
    stage.innerHTML = '';
    const clone = document.querySelector('.sheet-flyer').cloneNode(true);
    clone.style.transform = 'none';
    stage.appendChild(clone);
    document.body.dataset.print = 'flyer';
  });
  await page.emulateMedia({ media: 'print' });
  await page.pdf({ path: join(OUT, 'flyer.pdf'), printBackground: true, preferCSSPageSize: true });
  await page.emulateMedia({ media: 'screen' });

  // shared link new context
  const shareContext = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const shared = await shareContext.newPage();
  shared.on('pageerror', (e) => problems.push('shared pageerror: ' + e.message));
  await shared.goto(shareLink, { waitUntil: 'networkidle' });
  await shared.waitForTimeout(1500);
  await shared.screenshot({ path: join(OUT, 'shared-mobile.png'), fullPage: true });
  console.log('shared cards', await shared.locator('.req-card').count());
  console.log('shared highlight', await shared.locator('.req-card.is-shared').count());

  // mobile fresh
  const mctx = await browser.newContext({ viewport: { width: 390, height: 844 } });
  const m = await mctx.newPage();
  m.on('pageerror', (e) => problems.push('mobile pageerror: ' + e.message));
  await m.goto(URL, { waitUntil: 'networkidle' });
  await m.evaluate(() => document.fonts.ready);
  await m.waitForTimeout(600);
  console.log('mobile overflow-x', await m.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth));
  await m.screenshot({ path: join(OUT, 'mobile-hero.png') });
  for (const [id, name] of [['como-funciona', 'how'], ['pedidos', 'board'], ['preciso-de-ajuda', 'ask'], ['materiais', 'materials'], ['outras-formas', 'help']]) {
    await m.locator('#' + id).scrollIntoViewIfNeeded();
    await m.waitForTimeout(700);
    await m.screenshot({ path: join(OUT, `mobile-${name}.png`) });
  }
  await revealAll(m);
  await m.screenshot({ path: join(OUT, 'mobile-full.png'), fullPage: true });

  // sheet geometry
  const geo = await m.evaluate(() => {
    const out = {};
    for (const kind of ['poster', 'flyer']) {
      const sheet = document.querySelector('.sheet-' + kind);
      const frame = sheet.closest('.sheet-frame');
      const sr = sheet.getBoundingClientRect();
      const scale = sr.width / sheet.offsetWidth;
      out[kind] = {
        visible: sr.width > 0,
        frameW: frame.clientWidth, frameH: frame.clientHeight,
        scaledW: +sr.width.toFixed(1), scaledH: +sr.height.toFixed(1),
        tabsBottom: +((sheet.querySelector('.sheet-tabs').getBoundingClientRect().bottom - sr.top) / scale).toFixed(1),
        sheetH: sheet.offsetHeight
      };
    }
    return out;
  });
  console.log('geo', JSON.stringify(geo));

  console.log('PROBLEMS', problems.length ? problems : 'none');
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

