const { createRequire } = require('node:module');
const { join } = require('node:path');
const { mkdirSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const OUT = '/tmp/opencode/shots3';
mkdirSync(OUT, { recursive: true });
const URL = 'http://127.0.0.1:3002/';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 2 });
  const p = await ctx.newPage();
  await p.goto(URL, { waitUntil: 'networkidle' });
  await p.evaluate(() => localStorage.clear());
  await p.reload({ waitUntil: 'networkidle' });
  await p.evaluate(() => document.fonts.ready);
  await p.waitForTimeout(400);

  // create own request with long name
  await p.fill('#f-name', 'Maria Aparecida dos Santos');
  await p.fill('#f-phone', '11987654321');
  await p.fill('#f-hood', 'Jardim das Flores');
  await p.fill('#f-city', 'São Paulo');
  await p.fill('#f-reason', 'O gás acabou e estou sem trabalho esta semana. Tenho três crianças em casa.');
  await p.check('#f-consent');
  await p.locator('#request-form button[type=submit]').click();
  await p.waitForTimeout(400);
  await p.locator('#view-request').click();
  await p.waitForTimeout(900);
  const card = p.locator('.req-card').first();
  await card.scrollIntoViewIfNeeded();
  await p.waitForTimeout(300);
  await card.screenshot({ path: join(OUT, 'card-own.png') });
  const demo = p.locator('.req-card', { hasText: 'Marli' });
  await demo.screenshot({ path: join(OUT, 'card-demo.png') });
  await p.locator('#pedidos').screenshot({ path: join(OUT, 'board.png') });

  // flyer
  await p.locator('#materiais').scrollIntoViewIfNeeded();
  await p.waitForTimeout(700);
  await p.getByRole('tab', { name: 'Panfleto A5' }).click();
  await p.waitForTimeout(500);
  await p.locator('#panel-flyer').screenshot({ path: join(OUT, 'flyer-full.png') });
  await p.locator('.sheet-flyer .flyer-foot').screenshot({ path: join(OUT, 'flyer-foot.png') });
  await p.getByRole('tab', { name: 'Cartaz A4' }).click();
  await p.waitForTimeout(500);
  await p.locator('#panel-poster').screenshot({ path: join(OUT, 'poster-full.png') });

  // mobile
  const mctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
  const m = await mctx.newPage();
  await m.goto(URL, { waitUntil: 'networkidle' });
  await m.evaluate(() => document.fonts.ready);
  await m.waitForTimeout(500);
  // scroll to reveal
  const height = await m.evaluate(() => document.body.scrollHeight);
  for (let y = 0; y < height; y += 500) { await m.evaluate((v) => scrollTo(0, v), y); await m.waitForTimeout(60); }
  await m.evaluate(() => scrollTo(0, 0));
  await m.waitForTimeout(600);
  await m.screenshot({ path: join(OUT, 'mobile-hero.png') });
  await m.locator('#pedidos').scrollIntoViewIfNeeded();
  await m.waitForTimeout(500);
  await m.locator('.req-card').first().screenshot({ path: join(OUT, 'mobile-card.png') });
  await m.locator('#preciso-de-ajuda').scrollIntoViewIfNeeded();
  await m.waitForTimeout(500);
  await m.screenshot({ path: join(OUT, 'mobile-ask.png') });
  await m.locator('#materiais').scrollIntoViewIfNeeded();
  await m.waitForTimeout(700);
  await m.screenshot({ path: join(OUT, 'mobile-materials.png') });
  await m.locator('#outras-formas').scrollIntoViewIfNeeded();
  await m.waitForTimeout(500);
  await m.screenshot({ path: join(OUT, 'mobile-help.png') });
  await p.screenshot({ path: join(OUT, 'desktop-full.png'), fullPage: true });

  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

