const { createRequire } = require('node:module');
const { join } = require('node:path');
const { mkdirSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const OUT = '/tmp/opencode/shots4';
mkdirSync(OUT, { recursive: true });
(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1100, height: 900 }, deviceScaleFactor: 2 });
  const p = await ctx.newPage();
  await p.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
  await p.evaluate(() => localStorage.clear());
  await p.reload({ waitUntil: 'networkidle' });
  await p.evaluate(() => document.fonts.ready);
  await p.waitForTimeout(500);

  await p.locator('#materiais').scrollIntoViewIfNeeded();
  await p.waitForTimeout(600);
  await p.getByRole('tab', { name: 'Panfleto A5' }).click();
  await p.waitForTimeout(500);
  await p.locator('#panel-flyer').screenshot({ path: join(OUT, 'flyer.png') });
  await p.getByRole('tab', { name: 'Cartaz A4' }).click();
  await p.waitForTimeout(500);
  await p.locator('#panel-poster').screenshot({ path: join(OUT, 'poster.png') });

  // print media view
  await p.evaluate(() => {
    const stage = document.getElementById('print-stage');
    stage.innerHTML = '';
    const clone = document.querySelector('.sheet-poster').cloneNode(true);
    clone.style.transform = 'none';
    stage.appendChild(clone);
    document.body.dataset.print = 'poster';
  });
  await p.emulateMedia({ media: 'print' });
  await p.waitForTimeout(300);
  await p.locator('#print-stage').screenshot({ path: join(OUT, 'print-poster.png') });

  await p.evaluate(() => {
    const stage = document.getElementById('print-stage');
    stage.innerHTML = '';
    const clone = document.querySelector('.sheet-flyer').cloneNode(true);
    clone.style.transform = 'none';
    stage.appendChild(clone);
    document.body.dataset.print = 'flyer';
  });
  await p.waitForTimeout(300);
  await p.locator('#print-stage').screenshot({ path: join(OUT, 'print-flyer.png') });
  await p.emulateMedia({ media: 'screen' });

  // print PDFs again
  await p.evaluate(() => {
    const stage = document.getElementById('print-stage');
    stage.innerHTML = '';
    const clone = document.querySelector('.sheet-poster').cloneNode(true);
    clone.style.transform = 'none';
    stage.appendChild(clone);
    document.body.dataset.print = 'poster';
  });
  await p.emulateMedia({ media: 'print' });
  await p.pdf({ path: join(OUT, 'poster.pdf'), printBackground: true, preferCSSPageSize: true });
  await p.evaluate(() => {
    const stage = document.getElementById('print-stage');
    stage.innerHTML = '';
    const clone = document.querySelector('.sheet-flyer').cloneNode(true);
    clone.style.transform = 'none';
    stage.appendChild(clone);
    document.body.dataset.print = 'flyer';
  });
  await p.pdf({ path: join(OUT, 'flyer.pdf'), printBackground: true, preferCSSPageSize: true });
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

