const { createRequire } = require('node:module');
const { join } = require('node:path');
const rt = join(process.env.HOME, '.local/share/omgithub-playwright');
const req = createRequire(join(rt, 'package.json'));
const { chromium } = req('playwright');
(async () => {
  const b = await chromium.launch({ headless: true });
  const p = await b.newPage({ viewport: { width: 1440, height: 900 } });
  await p.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
  await p.waitForTimeout(400);
  await p.getByRole('tab', { name: 'Panfleto A5' }).click();
  await p.waitForTimeout(400);
  const info = await p.evaluate(() => {
    const sheet = document.querySelector('.sheet-flyer');
    const sr = sheet.getBoundingClientRect();
    const scale = sr.width / sheet.offsetWidth;
    const norm = (el) => {
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      return { top:+((r.top-sr.top)/scale).toFixed(1), bottom:+((r.bottom-sr.top)/scale).toFixed(1), h:+(r.height/scale).toFixed(1), mt:cs.marginTop, mb:cs.marginBottom, minH:cs.minHeight, flex:cs.flex, lineHeight:cs.lineHeight, font:cs.fontSize };
    };
    return {
      sheetH: sheet.offsetHeight,
      scale,
      inner: norm(sheet.querySelector('.sheet-inner')),
      foot: norm(sheet.querySelector('.flyer-foot')),
      tabs: norm(sheet.querySelector('.sheet-tabs')),
      lastTab: norm(sheet.querySelector('.tab')),
      footText: sheet.querySelector('.flyer-foot').innerText
    };
  });
  console.log(JSON.stringify(info,null,2));
  await b.close();
})();
EOF
