const { createRequire } = require('node:module');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const axePath = '/tmp/opencode/node_modules/axe-core/axe.min.js';

(async () => {
  const browser = await chromium.launch({ headless: true });
  for (const viewport of [{ width: 1440, height: 900 }, { width: 390, height: 844 }]) {
    const ctx = await browser.newContext({ viewport });
    const p = await ctx.newPage();
    await p.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
    await p.evaluate(() => localStorage.clear());
    await p.reload({ waitUntil: 'networkidle' });
    await p.addScriptTag({ path: axePath });
    const results = await p.evaluate(async () => {
      const r = await axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'] } });
      return r.violations.map(v => ({
        id: v.id, impact: v.impact, help: v.help,
        nodes: v.nodes.slice(0, 4).map(n => ({ target: n.target, summary: n.failureSummary }))
      }));
    });
    console.log(`\nVIEWPORT ${viewport.width}: ${results.length} violation(s)`);
    console.log(JSON.stringify(results, null, 2));
    await ctx.close();
  }
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

