const { createRequire } = require('node:module');
const { join } = require('node:path');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require2 = createRequire(join(runtime, 'package.json'));
const { chromium } = require2('playwright');
const axePath = '/tmp/opencode/node_modules/axe-core/axe.min.js';

(async () => {
  const browser = await chromium.launch({ headless: true });
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const p = await ctx.newPage();
  await p.goto('http://127.0.0.1:3002/', { waitUntil: 'networkidle' });
  await p.addScriptTag({ path: axePath });

  const scan = async (label) => {
    const r = await p.evaluate(async () => {
      const res = await axe.run(document, { runOnly: { type: 'tag', values: ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa'] } });
      return res.violations.map(v => ({ id: v.id, impact: v.impact, help: v.help, nodes: v.nodes.map(n => n.target) }));
    });
    console.log(label, JSON.stringify(r));
  };

  await p.getByRole('button', { name: /Configurar campanha/ }).click();
  await p.waitForTimeout(250);
  await scan('settings');

  await p.keyboard.press('Escape');
  await p.locator('footer').getByRole('button', { name: /Como tratamos/ }).click();
  await p.waitForTimeout(250);
  await scan('privacy');

  await p.keyboard.press('Escape');
  await p.fill('#f-name', 'Ana Teste');
  await p.fill('#f-phone', '11987654321');
  await p.fill('#f-hood', 'Centro');
  await p.fill('#f-city', 'São Paulo');
  await p.check('#f-consent');
  await p.locator('#request-form button[type=submit]').click();
  await p.waitForTimeout(350);
  await scan('success');

  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

